<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';

import {useI18n} from '@vben/locales';

import {AcademicError,call,type CatalogImport,type ImportPreview,Mutation,parseCatalogImport} from './api';
const props=defineProps<{disabled:boolean;schoolId:string;}>();const emit=defineEmits<{complete:[];pending:[value:boolean]}>();const {t}=useI18n();
const input=ref<CatalogImport>();const preview=ref<ImportPreview>();const error=ref('');const busy=ref(false);const uncertain=ref(false);const saved=ref(false);const mutation=new Mutation();let generation=0;
watch(()=>props.schoolId,()=>{generation++;input.value=undefined;preview.value=undefined;error.value=''});watch([busy,uncertain],()=>emit('pending',busy.value||uncertain.value));onBeforeUnmount(()=>{generation++;emit('pending',false)});onBeforeRouteLeave(()=>!uncertain.value&&!busy.value||window.confirm(t('page.academic.uncertain')));
async function choose(event:Event){const file=event.target instanceof HTMLInputElement?event.target.files?.[0]:undefined;const version=++generation;error.value='';preview.value=undefined;input.value=undefined;saved.value=false;if(!file)return;try{if(file.size>4*1024*1024)throw new AcademicError('invalid_input');const value=parseCatalogImport(await file.text());if(version!==generation)return;if(value.school_id!==props.schoolId)throw new AcademicError('forbidden');input.value=value}catch(error_){if(version===generation)error.value=error_ instanceof AcademicError?error_.code:'invalid_input'}}
async function inspect(){if(!input.value)return;busy.value=true;error.value='';try{preview.value=await call<ImportPreview>('catalog','/imports/preview','ImportPreview',{body:input.value,key:crypto.randomUUID()})}catch(error_){error.value=error_ instanceof AcademicError?error_.code:'unavailable'}finally{busy.value=false}}
async function confirm(){if(!input.value||!preview.value||busy.value)return;busy.value=true;error.value='';try{await mutation.run('catalog','/imports/confirm','ImportResult',{...input.value,preview_token:preview.value.preview_token});saved.value=true;preview.value=undefined;input.value=undefined;emit('complete')}catch(error_){error.value=error_ instanceof AcademicError?error_.code:'unavailable';if(error.value==='conflict')preview.value=undefined}finally{busy.value=false;uncertain.value=mutation.uncertain}}
</script>
<template><section class="admin-form"><h2>{{ t('page.academic.importTitle') }}</h2><label>{{ t('page.academic.importFile') }}<input type="file" accept="application/json,.json" :disabled="disabled || busy || uncertain" @change="choose" /></label><button :disabled="disabled || busy || uncertain || !input" @click="inspect">{{ t('page.academic.previewImport') }}</button><p v-if="error" role="alert">{{ t(`page.academic.errors.${error}`) }}</p><p v-if="saved" role="status">{{ t('page.academic.saved') }}</p><template v-if="preview"><p v-if="preview.code" role="alert">{{ t(`page.academic.errors.${preview.code}`) }}</p><ul class="admin-list"><li v-for="row in preview.changes" :key="row.kind + row.id"><span>{{ row.id }}</span> <strong>{{ t(`page.academic.operationStates.${row.state}`) }}</strong> <span v-if="row.fields.length > 0">{{ row.fields.join(', ') }}</span></li></ul><button :disabled="disabled || busy || !preview.valid" @click="confirm">{{ t(uncertain ? 'page.academic.retry' : 'page.academic.confirmImport') }}</button></template><p v-if="uncertain" role="status">{{ t('page.academic.uncertain') }}</p></section></template>
